# NightShift Orders Service (v1.0.1 with VIP bug)
import uuid
from fastapi import FastAPI, Request
from fastapi.responses import JSONResponse

app = FastAPI(title="Orders Service")

@app.get("/health")
def health():
    return {"status": "ok", "service": "orders", "version": "v1.0.1"}

@app.post("/orders")
async def create_order(request: Request):
    data = await request.json()
    price = float(data.get("price", 0.0))

    # VIP discount code feature (BUGGY: assumes discount is always a dict)
    discount = data.get("discount")
    discount_code = discount["code"]
    if discount_code == "VIP50":
        price = price * 0.50

    order_id = f"ord_{uuid.uuid4().hex[:8]}"
    return {"status": "created", "order_id": order_id, "price": price}
